S(electricity_status),toilet_hygiene_status=VALUES(toilet_hygiene_status),cleanliness_status=VALUES(cleanliness_status),kitchen_status=VALUES(kitchen_status),first_aid_status=VALUES(first_aid_status),fire_safety_status=VALUES(fire_safety_status),security_status=VALUES(security_status),complaints=VALUES(complaints),action_required=VALUES(action_required),remarks=VALUES(remarks),submitted_by=VALUES(submitted_by)";$s=mysqli_prepare($conn,$sql);mysqli_stmt_bind_param($s,$types,...$vals);if(!mysqli_stmt_execute($s))exit(mysqli_error($conn));log_activity('updated','wastigruh','Saved hostel daily status');flash('success','Wastigruh status saved.');redirect('wastigruh.php?date='.urlencode($_POST['report_date']??today()));
